import{_ as a,o as e,c as d,s as t}from"./index-c32c3a4d.js";const s={},r=t(`<p data-v-a54cf8ed>Subdiviser un réseau permet :</p><ul data-v-a54cf8ed><li data-v-a54cf8ed>De se calquer à la structure de l&#39;entreprise</li><li data-v-a54cf8ed>D&#39;optimiser les flux de trafic</li><li data-v-a54cf8ed>D&#39;éviter les phénomènes de contagion</li></ul><h2 data-v-a54cf8ed>Checklist</h2><ol data-v-a54cf8ed><li data-v-a54cf8ed>Déterminer les besoins (inclure les réserves)</li><li data-v-a54cf8ed> Calculer et réserver le nombre de bits nécessaires (Host_ID et Subnet_ID) </li><li data-v-a54cf8ed>Définir la classe et le Net_ID</li><li data-v-a54cf8ed>Déterminer le masque (réseau et sous-réseau)</li><li data-v-a54cf8ed>Calculer les adresses de chaque sous-réseau</li><li data-v-a54cf8ed>Réaliser l&#39;annuaire</li></ol><h2 data-v-a54cf8ed>Exemple avec un exercice disponible sur Moodle</h2><p data-v-a54cf8ed><a href="/network/files/projet_1.pdf" target="_blank" data-v-a54cf8ed>projet_1.pdf</a></p><hr data-v-a54cf8ed><h2 data-v-a54cf8ed>1) Déterminer les besoins (inclure les réserves)</h2><h3 data-v-a54cf8ed>Nombre d&#39;IP</h3><p data-v-a54cf8ed>On prend le plus grand sous-réseau, ici c&#39;est Lausanne.</p><p data-v-a54cf8ed> 10 + 5 + 5 + 2 = 22<br data-v-a54cf8ed> 22 + 1 (passerelle) = 23<br data-v-a54cf8ed> 23 + 10% = <strong data-v-a54cf8ed>26</strong> (arrondi supérieur) </p><h3 data-v-a54cf8ed>Nombre de sous-réseaux</h3><p data-v-a54cf8ed> Le patron prévoit 2 bureaux supplémentaires → 4 sous-réseaux<br data-v-a54cf8ed> 4 + 10% = <strong data-v-a54cf8ed>5</strong></p><hr data-v-a54cf8ed><h2 data-v-a54cf8ed> 2) Calculer et réserver le nombre de bits nécessaires (Host_ID et Subnet_ID) </h2><h3 data-v-a54cf8ed>Pour les sous-réseaux</h3><p data-v-a54cf8ed> Le nombre de sous-réseaux à partir du nombre de bits se calcul comme ça : SR = 2<sup data-v-a54cf8ed>n</sup> - 2 </p><p data-v-a54cf8ed>Ici, nous cherchons n, donc n = ln(SR + 2) / ln(2)</p><div class="alert-info" data-v-a54cf8ed>ln est le logarithme naturel</div><p data-v-a54cf8ed> ln(5 + 2) / ln(2) = ~2.807... → <strong data-v-a54cf8ed>3</strong><br data-v-a54cf8ed><a href="/network/medias/ti-30xpro-ln.png" target="_blank" data-v-a54cf8ed> Voir sur la calculatrice. </a></p><h3 data-v-a54cf8ed>Pour les IP</h3><p data-v-a54cf8ed> n = ln(IP + 2) / ln(2)<br data-v-a54cf8ed> ln(26 + 2) / ln(2) = ~4.807... → <strong data-v-a54cf8ed>5</strong></p><hr data-v-a54cf8ed><h2 data-v-a54cf8ed>3) Définir la classe et le Net_ID</h2><h3 data-v-a54cf8ed>La classe 😎</h3><p data-v-a54cf8ed> Soit n le nombre de bits pour l&#39;IP + le nombre de bits pour le sous-réseau,<br data-v-a54cf8ed> Si n ≤ 8 → Classe C<br data-v-a54cf8ed> Si n ≤ 16 → Classe B<br data-v-a54cf8ed> Si n ≤ 24 → Classe A </p><p data-v-a54cf8ed>Ici, ce sera donc une <strong data-v-a54cf8ed>classe C</strong>.</p><h3 data-v-a54cf8ed>Le NET_ID</h3><p data-v-a54cf8ed> Les adresses privées pour une classe C sont de 192.168.0.x à 192.168.255.x. Nous pouvons choisir par exemple <strong data-v-a54cf8ed>192.168.1.0</strong> comme NET_ID. </p><hr data-v-a54cf8ed><h2 data-v-a54cf8ed>4) Déterminer le masque (réseau et sous-réseau)</h2><p data-v-a54cf8ed> Nous avons une adresse constituée de :<br data-v-a54cf8ed> 24 bits pour le réseau<br data-v-a54cf8ed> 3 bits pour le sous-réseau<br data-v-a54cf8ed> 5 bits pour l&#39;host </p><p data-v-a54cf8ed>Structure bits à bits :</p><pre data-v-a54cf8ed>	RRRRRRRR.RRRRRRRR.RRRRRRRR.SSSHHHHH</pre><p data-v-a54cf8ed>Donc le masque :</p><pre data-v-a54cf8ed>	11111111.11111111.11111111.11100000</pre><p data-v-a54cf8ed>Ou en décimal :</p><pre data-v-a54cf8ed>	255.255.255.224</pre><p data-v-a54cf8ed> Le masque de réseau est 255.255.255.0 et le masque de sous-réseau est 255.255.255.224, se note aussi /27 car 27 bits à 1. </p><hr data-v-a54cf8ed><h2 data-v-a54cf8ed>5) Calculer les adresses de chaque sous-réseau</h2><p data-v-a54cf8ed> Ici, il faut écrire toutes les possibilités de sous-réseau, on doit supprimer le premier et le dernier : </p><pre data-v-a54cf8ed><s data-v-a54cf8ed>00000000</s>
00100000
01000000
01100000
10000000
10100000
11000000
<s data-v-a54cf8ed>11100000</s></pre><p data-v-a54cf8ed>On traduit en décimal. Le premier donne le pas.</p><pre data-v-a54cf8ed>00100000 = 32
01000000 = 64 (32 + 32)
01100000 = 96 (64 + 32)
10000000 = 128 (96 + 32)
10100000 = 160 (128 + 32)
11000000 = 192 (160 + 32)</pre><hr data-v-a54cf8ed><h2 data-v-a54cf8ed>6) Réaliser l&#39;annuaire</h2><ul data-v-a54cf8ed><li data-v-a54cf8ed>Adresse du sous-réseau = les adresses calculées précédemment</li><li data-v-a54cf8ed>Première adresse IP = l&#39;adresse du sous-réseau + 1</li><li data-v-a54cf8ed>Adresse de diffusion = l&#39;adresse du prochain sous-réseau - 1</li><li data-v-a54cf8ed>Dernière adresse IP = l&#39;adresse de diffusion - 1</li></ul><table data-v-a54cf8ed><tr data-v-a54cf8ed><th data-v-a54cf8ed>Adresse du sous-réseau</th><th data-v-a54cf8ed>Première adresse IP</th><th data-v-a54cf8ed>Dernière adresse IP</th><th data-v-a54cf8ed>Adresse de diffusion</th></tr><tr data-v-a54cf8ed><td data-v-a54cf8ed>192.168.1.32</td><td data-v-a54cf8ed>192.168.1.33</td><td data-v-a54cf8ed>192.168.1.62</td><td data-v-a54cf8ed>192.168.1.63</td></tr><tr data-v-a54cf8ed><td data-v-a54cf8ed>192.168.1.64</td><td data-v-a54cf8ed>192.168.1.65</td><td data-v-a54cf8ed>192.168.1.94</td><td data-v-a54cf8ed>192.168.1.95</td></tr><tr data-v-a54cf8ed><td data-v-a54cf8ed>192.168.1.96</td><td data-v-a54cf8ed>192.168.1.97</td><td data-v-a54cf8ed>192.168.1.126</td><td data-v-a54cf8ed>192.168.1.127</td></tr><tr data-v-a54cf8ed><td data-v-a54cf8ed>192.168.1.128</td><td data-v-a54cf8ed>192.168.1.129</td><td data-v-a54cf8ed>192.168.1.158</td><td data-v-a54cf8ed>192.168.1.159</td></tr><tr data-v-a54cf8ed><td data-v-a54cf8ed>192.168.1.160</td><td data-v-a54cf8ed>192.168.1.161</td><td data-v-a54cf8ed>192.168.1.190</td><td data-v-a54cf8ed>192.168.1.191</td></tr><tr data-v-a54cf8ed><td data-v-a54cf8ed>192.168.1.192</td><td data-v-a54cf8ed>192.168.1.193</td><td data-v-a54cf8ed>192.168.1.222</td><td data-v-a54cf8ed>192.168.1.223</td></tr></table>`,49),c=[r];function l(f,v){return e(),d("div",null,c)}const i=a(s,[["render",l],["__scopeId","data-v-a54cf8ed"]]);export{i as default};
